# ---- writer + assertions ----
assert set(P.keys()) == set(IDS), f"id set mismatch: {set(IDS)^set(P.keys())}"
assert len(P) == 27, len(P)
for cid in IDS:
    d = P[cid]
    assert set(d.keys()) == {"prediction_text","basis","confidence","trigger"}, (cid, d.keys())
    assert isinstance(d["confidence"], float) and 0.0 <= d["confidence"] <= 1.0, cid
    t = d["trigger"]
    assert set(t.keys()) == {"changed_main","reserve_used","disputed","reason"}, cid
    assert all(isinstance(t[k], bool) for k in ("changed_main","reserve_used","disputed")), cid
    out = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
           "confidence": d["confidence"], "trigger": t}
    (OUT / f"{cid}.json").write_text(json.dumps(out, ensure_ascii=False, indent=1), encoding="utf-8")

# verify per-id, no glob
n = 0
for cid in IDS:
    p = OUT / f"{cid}.json"
    assert p.exists(), cid
    back = json.loads(p.read_text(encoding="utf-8"))
    assert back["case_id"] == cid and back["prediction_text"] and back["basis"], cid
    n += 1
cm = sum(P[c]["trigger"]["changed_main"] for c in IDS)
ru = sum(P[c]["trigger"]["reserve_used"] for c in IDS)
di = sum(P[c]["trigger"]["disputed"] for c in IDS)
print(f"WROTE {n} files; trigger counts: changed_main={cm} reserve_used={ru} disputed={di}")
